new_banner = f"""    <!-- Static Banner -->
    <div class="bg-black text-white py-3 flex items-center justify-center border-b border-black relative z-30 px-4">
        <div class="flex items-center space-x-2 text-[10px] sm:text-xs tracking-[0.15em] uppercase">
            {svg_code}
            <span class="font-bold text-sm sm:text-base tracking-[0.2em]">Newclip Technics</span>
            <span class="opacity-60 px-2 sm:px-3">—</span>
            <span class="opacity-90 font-medium">Osteosynthesis Solutions</span>
        </div>
    </div>"""

for file in ['index.html', 'booking.html']:
    try:
        with open(file, 'r', encoding='utf-8') as f:
            content = f.read()
            
        pattern = r'<!-- Marquee Banner -->\s*<div class="overflow-hidden bg-black text-white py-3 whitespace-nowrap flex items-center border-b border-black relative z-30">.*?</style>\s*<div class="animate-marquee-scroll[^>]*>.*?</div>\s*</div>'
        new_content = re.sub(pattern, new_banner, content, flags=re.DOTALL)
        
        if content != new_content:
            with open(file, 'w', encoding='utf-8') as f:
                f.write(new_content)
    except Exception as e:
        print(f"Error processing {file}: {e}")

print("Done index")
